function TCheckpoints.Best: string;
var
  A: TStringArray;
  I: Integer;
  V, BestV: Double;
begin
  Result := '';
  BestV := Infinity;
  A := List;
  for I := 0 to High(A) do
  begin
    V := ReadRunState(A[I]).ValLoss;
    if not IsNan(V) and (V < BestV) then
    begin
      BestV := V;
      Result := A[I];
    end;
  end;
end;

procedure TCheckpoints.Prune;
var
  A: TStringArray;
  B: string;
  I: Integer;
begin
  A := List;
  B := Best;
  for I := 0 to High(A) - FKeep do
    if A[I] <> B then
      RemoveTree(A[I]);
end;

